import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { EncryptionService } from "modules/encryption/service/EncryptionService";
import { SecureStoreKeys } from "modules/matrix-client/models";
import { type FC, useState } from "react";
import { KeyboardAvoidingView, Platform, StyleSheet } from "react-native";
import { useMMKVBoolean } from "react-native-mmkv";
import Toast from "react-native-toast-message";
import {
  Button,
  GoBackHeader,
  Input,
  IpadScreenWrapper,
  Loading,
  ScreenLayout,
} from "shared/components";
import { useNavigateToCorrectScreenHelper } from "shared/hooks";
import { Colors, TextSize } from "shared/styles";
import { offlineToastHelper } from "shared/utils";

export const EnterRecoveryKey: FC<
  NativeStackScreenProps<Routes, "enterRecoveryKey">
> = () => {
  const [recoveryKey, setRecoveryKey] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [hasSeenProtectAccountMessage, setHasSeenProtectAccountMessage] =
    useMMKVBoolean(SecureStoreKeys.HAS_SEEN_PROTECT_ACCOUNT_MESSAGE);
  const navigateToCorrectScreen = useNavigateToCorrectScreenHelper();

  const handleContinue = async () => {
    if (!recoveryKey.trim()) return;

    try {
      setIsLoading(true);
      // The recover() method both restores encrypted messages AND verifies the device
      await EncryptionService.recoverWithKey(recoveryKey);

      // Check whether recover() fully resolved the Incomplete state.
      // If local secrets (e.g. the backup decryption key) were never uploaded
      // to SSSS, recover() alone won't fix it — resetRecoveryKey() re-uploads
      // ALL current local secrets under a new key, which is the only SDK path
      // that reliably transitions Incomplete → Enabled in that scenario.
      // const stateAfterRecover = await EncryptionService.getRecoveryState();
      // if (stateAfterRecover === RecoveryState.Incomplete) {
      //   const newKey = await EncryptionService.resetRecoveryKey();
      //   if (!hasSeenProtectAccountMessage) {
      //     setHasSeenProtectAccountMessage(true);
      //   }
      //   // Navigate to setUpRecoveryKey so the user can save their new key
      //   NavigationContainerRef.reset({
      //     index: 0,
      //     routes: [
      //       { name: "home" },
      //       { name: "setUpRecoveryKey", params: { initialKey: newKey } },
      //     ],
      //   });
      //   return;
      // }

      Toast.show({
        text1: "Device verified successfully!",
        text2: "You can now access your encrypted messages",
        type: "success",
      });

      if (!hasSeenProtectAccountMessage) setHasSeenProtectAccountMessage(true);

      navigateToCorrectScreen();
    } catch (error) {
      console.error(error);
      offlineToastHelper(
        "Invalid recovery key",
        "Please check your recovery key and try again",
      );
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <ScreenLayout type="modal">
      {isLoading && <Loading text="Verifying with recovery key..." />}
      <GoBackHeader margins={{ marginBottom: 40 }} />
      <Block flex={1}>
        <KeyboardAvoidingView
          style={styles.keyboardAvoidingView}
          behavior={Platform.OS === "ios" ? "padding" : "height"}
        >
          <IpadScreenWrapper justify="space-between" flex={1}>
            <Block justify="center" align="center" gap={32}>
              <Block gap={8}>
                <Text
                  size={TextSize.large}
                  textAlign="center"
                  font="InstrumentSans-Medium"
                >
                  Enter your recovery key
                </Text>
                <Text
                  textAlign="center"
                  font="InstrumentSans-Regular"
                  color={Colors.white50}
                >
                  This will verify your device and restore access to your
                  encrypted message history. Make sure nobody can see this
                  screen.
                </Text>
              </Block>

              <Block width="100%">
                <Input
                  placeholder="Recovery key"
                  value={recoveryKey}
                  onChangeText={setRecoveryKey}
                  autoCapitalize="none"
                  autoCorrect={false}
                  secureTextEntry
                />
              </Block>
            </Block>

            <Block
              width="100%"
              paddings={[0, 52]}
              margins={{ marginBottom: 20 }}
            >
              <Button.Primary
                size="medium"
                width="100%"
                onPress={handleContinue}
                disabled={!recoveryKey.trim()}
              >
                Continue
              </Button.Primary>
            </Block>
          </IpadScreenWrapper>
        </KeyboardAvoidingView>
      </Block>
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  keyboardAvoidingView: {
    flex: 1,
  },
});

