import {
  Block,
  type PaddingStyles,
  Screen,
  type ScreenProps,
} from "@prototyp/skeletor";
import type { PropsWithChildren } from "react";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { Colors } from "shared/styles";
import { isIpad } from "shared/utils";

type Props = PropsWithChildren<{
  background?: ScreenProps["background"];
  scrollable?: boolean;
  /** Effectively does not render the safe area, so the layout will span the full device screen realestate.
   * Example usage is on the Splash screen, where we have a full screen image to show.
   * Only use for fullscreen overlays or non-interactive screens, otherwise some layout elements might be hidden by native toolbars / notches.*/
  fullscreen?: boolean;
  /** Modal screens have a different top inset because they are offset from the device edge, so the default safe area inset is too large.
   * Defaults to "screen"
   */
  type?: "screen" | "modal";
  paddings?: PaddingStyles;
}>;

export const ScreenLayout: React.FC<Props> = ({
  scrollable,
  background,
  fullscreen,
  children,
  paddings,
  type = "screen",
}) => {
  const insets = useSafeAreaInsets();
  const verticalPaddings = fullscreen
    ? undefined
    : {
        paddingTop: type === "modal" ? 24 : insets.top,
        paddingBottom: isIpad() ? 20 : insets.bottom,
        paddingHorizontal: 20,
      };
  const isModal = type === "modal" && !isIpad();

  return (
    <Screen
      hideBottomSafeArea
      hideTopSafeArea
      background={background}
      scrollable={scrollable}
      paddings={Object.assign({}, verticalPaddings, paddings)}
    >
      {isModal && (
        <Block
          paddings={{ paddingTop: 12, paddingBottom: 40 }}
          background="transparent"
          align="center"
          justify="center"
        >
          <Block
            width={88}
            height={4}
            background={Colors.white50}
            border={{ borderRadius: 4 }}
          />
        </Block>
      )}
      {children}
    </Screen>
  );
};

